class={[
                "min-w-0 shrink",
                notes !== null && "ms-(--settings-hang) me-auto",
                notes === null && "last:me-(--settings-hang)",
              ]}

props.title:
title={unreported
          ? "Read from this session's next turn — it has not said which model answers"
          : value || "The model the harness picks for itself"}

props.onEscapeKeydown:
onEscapeKeydown={(event) => {
        // The panel's escape layer takes Esc before the window hears it, so
        // Esc unwinds from the innermost here: the card, then Comment or
        // Draw back to Interact, then the panel itself; the split's
        // expansion is the next Esc's.
        if (openPin || mode !== "interact") {
          event.preventDefault();
          pressKey("Escape");
        }
      }}

props.onkeydown:
onkeydown={(event) => {
          if (event.key === "Escape") {
            event.stopPropagation();
            draft = null;
            problem = null;
          }
          if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
            save();
          }
        }}

onkeydown={(event) => {
        if (event.key === "Escape" && under) {
          event.stopPropagation();
          addingUnder = null;
          addText = "";
        }
      }}

props.aria-label:
aria-label="Why {spec.name} did not install on {machineLabel(
                machine.hostname
              )}"

aria-label={commandOpen
                ? "Show the command on one line"
                : "Show the whole command"}

props.onkeydown:
onkeydown={(event) => {
              if (event.key === "Escape") {
                event.stopPropagation();
                titleDraft = null;
                titleProblem = null;
              }
            }}

