props.onCloseAutoFocus:
onCloseAutoFocus={(event) => {
        // Focus goes back to him without the ring: a ring left on him at
        // rest reads as a state he is in.
        event.preventDefault();
        lead.anchor?.focus({ focusVisible: false } as FocusOptions);
      }}

props.onOpenAutoFocus:
onOpenAutoFocus={(event) => {
        event.preventDefault();
        // The caret in his composer, where a keyboard is at hand: on touch
        // it would raise the screen's keyboard over the page.
        if (fine.current) {
          lead.draft.focusWanted = true;
        }
      }}

props.oninput:
oninput={(event) => {
            const raw = event.currentTarget.value;
            draft.handler.timeout = raw === "" ? undefined : Number(raw);
          }}

props.placeholder:
placeholder={"#!/bin/bash
set -euo pipefail

# The event JSON arrives on stdin."}

props.onchange:
onchange={(event) => {
          mode = (event.currentTarget as HTMLSelectElement).value as
            "port" | "host";
          refused = undefined;
        }}

props.onkeydown:
onkeydown={(event: KeyboardEvent) => {
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          event.preventDefault();
          reply();
        }
      }}

props.onDraggingChange:
onDraggingChange={(dragging) => {
        resizing = dragging;
        if (dragging) {
          dragFrom = savedWidth;
        } else if (expandAsked) {
          // A drag that ends at the edge was never a width: going back
          // gives the one it started from.
          keepWidth(dragFrom);
        }
      }}

props.onkeydown:
onkeydown={(event: KeyboardEvent) => {
            if (event.key === "Delete" || event.key === "Backspace") {
              event.preventDefault();
              remove(artifact);
            }
          }}
